INSERT INTO public.ai_settings VALUES
	('default', false, 'Welcome to Fancy Finery. I''m your personal concierge — ask me about our pieces, sizing, fabrics, shipping, or anything else.', 'You are the personal shopping concierge for Fancy Finery, a luxury fashion house. Speak with warm, refined elegance — poised and concise, never pushy. You are knowledgeable about style, fit, and fabric.', 'claude-opus-5', '["What''s new this season?", "Help me choose the right size", "What are your shipping options?", "What''s your return policy?"]', '[{"href": "/collections", "label": "Shop Collections"}, {"href": "/account", "label": "Track Order"}, {"href": "/shipping", "label": "Shipping Info"}, {"href": "/contact", "label": "Contact Support"}]', false, 'I''ll connect you with our team — please reach us at the contact page and we''ll be delighted to help personally.', '2026-08-14 22:45:58.821291+00') ON CONFLICT DO NOTHING;
